export function lineCells(origin: GridCell, li: LineInput): GridCell[] {
  const lengthCells = Math.floor(li.sizeFt / li.gridSizeFt);
  const halfWidth = (li.widthFt / li.gridSizeFt) * HALF;
  const snapped = snapAngle(li.angleDeg, SNAP_COMPASS);
  const rad = snapped * DEG_TO_RAD;
  const cosA = Math.cos(rad);
  const sinA = Math.sin(rad);
  const cells: GridCell[] = [];
  const b = { mapW: li.mapW, mapH: li.mapH };

  // Rotated-rectangle hit test: rotate each cell offset into beam space, keeping
  // forward distance `along` and (unsigned) sideways distance `perp`. Scan +1
  // past lengthCells so rotated corners that round into range are not clipped.
  const scan = lengthCells + 1;
  for (let dx = -scan; dx <= scan; dx++) {
    for (let dy = -scan; dy <= scan; dy++) {
      if (dx === 0 && dy === 0) continue;
      if (Math.max(Math.abs(dx), Math.abs(dy)) > lengthCells) continue;
      const along = dx * cosA + dy * sinA;
      const perp = Math.abs(-dx * sinA + dy * cosA);
      // along > 0 is the half-open gate: drop the origin and the backward half so
      // the line projects only forward; perp <= halfWidth keeps it within the band.
      if (along > 0 && perp <= halfWidth) {
        const c = { x: origin.x + dx, y: origin.y + dy };
        if (inBounds(c, b)) cells.push(c);
      }
    }
  }
  return cells;
}

