function parseEquipmentOptions(bg: BackgroundJson): EquipmentOptionParsed[] | null {
  const optionSet = bg.equipment_options?.[0];
  if (!optionSet) return null;
  const result: EquipmentOptionParsed[] = [];

  for (const opt of optionSet.from.options) {
    if (opt.option_type === "money") {
      result.push({ label: "B", items: [], gold: opt.count });
    } else {
      const items: EquipmentOptionItemParsed[] = [];
      let gold = 0;
      for (const item of opt.items) {
        const parsed = parseMultipleItem(item);
        gold += parsed.gold;
        if (parsed.item) items.push(parsed.item);
      }
      result.push({ label: "A", items, gold });
    }
  }
  return result.length > 0 ? result : null;
}

